import h5py
import sys
import os

h5_path = sys.argv[1]

with h5py.File(h5_path, 'r') as f:
    print(f'=== File attributes ===')
    for key, val in f.attrs.items():
        print(f'{key}: {val}')
    print(f'=== Keys in file (datasets, groups) ===')
    def recurse_group(g, prefix=""):
        for name in g:
            item = g[name]
            if isinstance(item, h5py.Dataset):
                print(f'Dataset: {prefix}{name}, shape: {item.shape}, dtype: {item.dtype}')
                for k,v in item.attrs.items():
                    print(f'    attr: {k}={v}')
            elif isinstance(item, h5py.Group):
                print(f'Group: {prefix}{name}/')
                for k,v in item.attrs.items():
                    print(f'    attr: {k}={v}')
                recurse_group(item, prefix+name+"/")
    recurse_group(f)
